import base64
import html
import os
import secrets
from typing import Any

from fastapi import APIRouter, Header, HTTPException, Query
from fastapi.responses import HTMLResponse
from pydantic import BaseModel

from database import Database

router = APIRouter()
STAGES = [("NEW", "🔎 Discovered"), ("VERIFIED", "🧹 Verified"), ("QUALIFIED", "🎯 Qualified"), ("RESEARCHED", "📋 Researched"), ("MESSAGE_GENERATED", "✉️ Message generated"), ("CONTACTED", "📤 Contacted"), ("RESPONDED", "💬 Replied"), ("MEETING", "📅 Meeting"), ("PROPOSAL", "📄 Proposal"), ("WON", "💰 Won"), ("LOST", "❌ Lost")]


def authorized(value: str | None) -> bool:
    user, password = os.getenv("DASHBOARD_USER", "").strip(), os.getenv("DASHBOARD_PASSWORD", "").strip()
    if not user or not password or not value or not value.startswith("Basic "):
        return False
    try:
        supplied_user, supplied_password = base64.b64decode(value[6:]).decode().split(":", 1)
        return secrets.compare_digest(supplied_user, user) and secrets.compare_digest(supplied_password, password)
    except Exception:
        return False


def require_dashboard(value: str | None) -> None:
    if not authorized(value):
        raise HTTPException(401, "Dashboard authentication required", headers={"WWW-Authenticate": "Basic"})


class StatusUpdate(BaseModel):
    status: str


def esc(value: Any) -> str:
    return html.escape(str(value if value is not None else ""), quote=True)


